// Build a strict-JSON extraction prompt for the agent's free-text reply.
const trig = $('When Called by WF1').first().json;
const fu = $('Get Active Followup').first().json;
const system = `Eres un asistente que interpreta el reporte de un asesor inmobiliario sobre un lead.
Etapa actual del lead: ${fu.current_stage}.
Etapas validas: new, contacted, qualified, visit_scheduled, offer, closed_won, closed_lost.

Devuelve SOLO un objeto JSON (sin texto extra) con esta forma:
{
  "stage": "<una de las etapas validas, la mas avanzada que implique el mensaje>",
  "note": "<resumen corto del avance en espanol>",
  "next_action": "<proximo paso o null>",
  "next_action_at": "<fecha ISO 8601 si el asesor menciono una fecha/hora concreta, o null>",
  "confirmation": "<una frase corta para confirmar al asesor lo que registraste>"
}
Reglas: si el mensaje no implica avance claro, mantiene la etapa actual. Si menciona 'visita/cita' usa visit_scheduled. Si menciona 'cerro/vendido/rentado' usa closed_won. Si 'no le interesa/perdido' usa closed_lost. Interpreta fechas relativas (ej. 'el viernes') segun la fecha de hoy ${new Date().toISOString().slice(0,10)}.`;
const chatMessages = [ { role:'system', content: system }, { role:'user', content: trig.text } ];
return [{ json: { chatMessages, followup_id: fu.followup_id, conversation_id: fu.conversation_id, agent_id: trig.agent_id, agent_phone: trig.agent_phone, lead_name: fu.lead_name, raw_text: trig.text } }];

// Parse the LLM JSON. Strip markdown fences / prose by slicing between first { and last }.
const ctx = $('Build Parse Prompt').first().json;
const resp = $input.first().json;
let raw='';
try { raw = resp.choices[0].message.content || ''; } catch(e) { raw=''; }
raw = String(raw).trim();
const a = raw.indexOf('{');
const b = raw.lastIndexOf('}');
if (a >= 0 && b > a) { raw = raw.slice(a, b + 1); }
let parsed={};
try { parsed = JSON.parse(raw); } catch(e) {
  parsed = { stage: null, note: ctx.raw_text, next_action: null, next_action_at: null, confirmation: 'Anotado.' };
}
const valid=['new','contacted','qualified','visit_scheduled','offer','closed_won','closed_lost'];
const stage = valid.includes(parsed.stage) ? parsed.stage : null;
return [{ json: {
  followup_id: ctx.followup_id,
  conversation_id: ctx.conversation_id,
  agent_id: ctx.agent_id,
  agent_phone: ctx.agent_phone,
  raw_text: ctx.raw_text,
  stage,
  note: parsed.note || ctx.raw_text,
  next_action: parsed.next_action || null,
  next_action_at: parsed.next_action_at || null,
  confirmation: parsed.confirmation || 'Anotado.'
} }];

